import json, os, pathlib, platform, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return root, payload

def messages(payload):
    return [item['message'] for item in payload['items']]

_, host_from_device = verify('gpu_diag_host_from_device', '''
    host fn load() -> i32 {
        return 1
    }
    device fn helper() -> i32 {
        return load()
    }
    kernel fn launch(output: GpuSlice<i32>) -> void {
        output[0] = helper()
    }
''', 1)
assert any('device function `helper` cannot call host function `load`' in message for message in messages(host_from_device)), host_from_device
assert any('kernel function `launch` cannot call host function `load`' in message for message in messages(host_from_device)), host_from_device

_, unsupported_device_type = verify('gpu_diag_unsupported_device_type', '''
    device fn bad(buffer: GpuBuffer<f32>) -> i32 {
        discard buffer
        return 0
    }
''', 1)
assert any('device function `bad` parameter `buffer` uses unsupported device type `GpuBuffer<f32>`' in message for message in messages(unsupported_device_type)), unsupported_device_type

_, alias_violation = verify('gpu_diag_alias_violation', '''
    use core.gpu;
    kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>) -> void {
        let i = gpu.global_id_x();
        output[i] = input[i];
    }
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let view = gpu.slice(buffer, 0, 8)
        let event = gpu.launch2(copy, 1, 8, view, view)
        gpu.wait(event)
        discard view
        gpu.free(buffer)
        return 0
    }
''', 1)
assert any('aliases GpuSlice parameters `input` and `output` through owner `buffer`' in message for message in messages(alias_violation)), alias_violation

_, barrier_misuse = verify('gpu_diag_barrier_misuse', '''
    use core.gpu;
    kernel fn bad(output: GpuSlice<f32>, n: i32) -> void {
        let i = gpu.global_id_x();
        if i < n {
            gpu.barrier();
            output[i] = 1.0;
        }
    }
''', 1)
assert any('kernel function `bad` cannot use `gpu.barrier` inside divergent control flow' in message for message in messages(barrier_misuse)), barrier_misuse

_, backend_shape = verify('gpu_diag_backend_shape', '''
    struct Pair { x: f32, y: f32 }
    use core.gpu;
    kernel fn blend(input: GpuSlice<f32>, coeff: Pair, output: GpuSlice<f32>) -> void {
        let i = gpu.global_id_x();
        output[i] = input[i] + coeff.x + coeff.y;
    }
''', 1)
assert any('kernel function `blend` parameter `coeff` uses type `Pair` that is not yet supported by the stable GPU launch ABI' in message for message in messages(backend_shape)), backend_shape

if platform.system() == 'Darwin':
    runtime_root = write_project('gpu_diag_runtime_launch_failure', '''
        use core.gpu;
        kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>, n: i32) -> void {
            let i = gpu.global_id_x();
            if i < n {
                output[i] = input[i];
            }
        }
        host fn main() -> i32 {
            let dev = gpu.default_device();
            let input = gpu.alloc_f32(dev, 4);
            let output = gpu.alloc_f32(dev, 4);
            let event = gpu.launch3(copy, 1, 1000000, gpu.slice(input, 0, 4), gpu.slice(output, 0, 4), 4);
            gpu.wait(event);
            gpu.free(input);
            gpu.free(output);
            return 0;
        }
    ''')
    build = subprocess.run([str(fz), 'build', str(runtime_root), '--json'], cwd=str(repo), capture_output=True, text=True)
    build_payload = json.loads(build.stdout.strip())
    assert build.returncode == 0, (build.returncode, build_payload, build.stderr)
    native = subprocess.run([build_payload['output']], cwd=str(repo), capture_output=True, text=True, env=dict(os.environ, FZ_NATIVE_DEBUG_ERRORS='1'))
    assert native.returncode == 0, (native.returncode, native.stdout, native.stderr)
    assert 'gpu.launch failed: block 1000000 exceeds Metal max threads-per-threadgroup' in native.stderr, native.stderr
    assert 'gpu.wait failed: invalid GPU event handle' in native.stderr, native.stderr
